-- Fase 1B: abertura da contratação pela matriz de contratação (a matriz é a mesma para todas as obras).
-- Só acrescenta tabela e colunas; troca a função de abertura (a da 1A sai, a nova entra).
-- Dados: docs/dados/matriz-contratacao.json (Matriz Contratos e Medição, REV 02).

create table public.matriz_contratacao (
  id uuid primary key default gen_random_uuid(),
  ordem int not null unique,
  grupo_codigo text not null,
  grupo text not null,
  subgrupo_codigo text,
  subgrupo text,
  atividade text not null,
  forma_legal text not null,
  unidade_negociacao text,
  tipo text check (tipo is null or tipo in ('mao_de_obra', 'material', 'material_e_mao_de_obra')),
  lotes text,
  unidade_medicao text,
  criterio_apropriacao text,
  observacoes text
);
alter table public.matriz_contratacao enable row level security;
create policy matriz_ler on public.matriz_contratacao for select to authenticated using (app.usuario_interno_ativo());

alter table public.contratacoes
  add column matriz_id uuid references public.matriz_contratacao (id) on delete set null,
  add column forma_legal text;
comment on column public.contratacoes.forma_legal is 'Forma legal da atividade da matriz no momento da abertura. Contratações antigas ficam sem.';


-- Abertura: a atividade da matriz substitui o serviço da EAP e o tipo de contrato. A forma legal vem da atividade;
-- fica a marcação de aditivo (que exige o contrato original) e a escolha de quem negocia.
drop function public.abrir_contratacao(uuid, text, uuid, numeric, public.tipo_contratacao, text, text);
create function public.abrir_contratacao(
  p_obra uuid, p_servico text, p_matriz uuid, p_valor numeric, p_aditivo boolean, p_negociacao text,
  p_contrato_original text default null
) returns uuid
language plpgsql security definer set search_path = '' as $$
declare
  v_id uuid;
  v_ano text := to_char(now() at time zone 'America/Sao_Paulo', 'YYYY');
  v_limite numeric := coalesce((select (valor #>> '{}')::numeric from public.parametros where chave = 'limite_escolha_obra_reais'), 4000);
  v_m public.matriz_contratacao;
  v_original text := nullif(btrim(coalesce(p_contrato_original, '')), '');
begin
  if not app.pode_agir_como('coordenador_obra', p_obra) then
    raise exception 'Só o coordenador da obra abre contratação.' using errcode = '42501';
  end if;
  if not exists (select 1 from public.obras where id = p_obra and ativa) then
    raise exception 'Obra inválida.' using errcode = 'P0001';
  end if;
  select * into v_m from public.matriz_contratacao where id = p_matriz;
  if not found then raise exception 'Escolha a atividade da matriz.' using errcode = 'P0001'; end if;
  if p_valor is not null and p_valor <= 0 then raise exception 'Valor Orçamento inválido.' using errcode = 'P0001'; end if;
  if p_negociacao not in ('obra', 'suprimentos') then raise exception 'Escolha quem negocia.' using errcode = 'P0001'; end if;
  if p_negociacao = 'obra' and p_valor is not null and p_valor >= v_limite then
    raise exception '%', 'A partir de R$ ' || replace(to_char(v_limite, 'FM999G999G990'), ',', '.') || ' do orçamento, a negociação é de Suprimentos.'
      using errcode = 'P0001';
  end if;
  if coalesce(p_aditivo, false) then
    if v_original is null then raise exception 'Informe o nº do contrato original no Sienge.' using errcode = 'P0001'; end if;
    perform app.conferir_codigo_sienge(p_obra, v_original);
  else
    v_original := null;
  end if;
  values (
    'CT-' || v_ano || '-' || lpad(nextval('public.contratacoes_numero')::text, 3, '0'),
    p_obra, btrim(p_servico), left(coalesce(v_m.subgrupo_codigo, v_m.grupo_codigo) || ' ' || v_m.atividade, 120),
    v_m.id, v_m.forma_legal, p_valor,
    case when coalesce(p_aditivo, false) then 'aditivo' else 'contrato' end::public.tipo_contratacao,
    p_negociacao, v_original,
    coalesce((select valor from public.parametros where chave = 'prazos_etapas'), '{}'),
    v_limite
  ) returning id into v_id;
  perform app.liberar_etapas(v_id);
  return v_id;
end $$;
revoke all on function public.abrir_contratacao(uuid, text, uuid, numeric, boolean, text, text) from public, anon;
grant execute on function public.abrir_contratacao(uuid, text, uuid, numeric, boolean, text, text) to authenticated;
